<?php
if($page==='location'){
  $id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT l.*,COALESCE(AVG(r.rating),0) avg_rating,COUNT(r.id) review_count FROM locations l LEFT JOIN reviews r ON r.location_id=l.id AND r.status='published' WHERE l.id=? AND l.status='active' GROUP BY l.id");$s->execute([$id]);$loc=$s->fetch();if(!$loc){http_response_code(404);exit('Location not found.');}$reviews=$pdo->prepare("SELECT r.*,u.name FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.location_id=? AND r.status='published' ORDER BY r.created_at DESC LIMIT 20");$reviews->execute([$id]);layout_start($loc['name']);?>
  <section class="container detail-grid section"><div><div class="detail-image" style="<?=$loc['image_url']?'background-image:url(\''.e($loc['image_url']).'\')':''?>"><?php if(!$loc['image_url']):?><span><?=e(strtoupper(substr($loc['city'],0,1)))?></span><?php endif;?></div><span class="eyebrow"><?=e($loc['city'])?> · <?=e($loc['country'])?></span><h1><?=e($loc['name'])?></h1><p class="lead"><?=e($loc['address'])?></p><div class="fact-row"><div><small>Hours</small><strong><?=e($loc['opening_hours'])?></strong></div><div><small>Price</small><strong><?=e(money((float)$loc['price_per_bag']))?>/bag/day</strong></div><div><small>Rating</small><strong>★ <?=number_format((float)$loc['avg_rating'],1)?> (<?=(int)$loc['review_count']?>)</strong></div></div><div class="copy-block"><h2>About this location</h2><p><?=nl2br(e($loc['description']?:'Convenient luggage storage with simple booking and secure reservation management.'))?></p></div><div class="copy-block"><h2>Recent reviews</h2><?php $rv=$reviews->fetchAll();if(!$rv):?><p class="muted">No reviews yet.</p><?php else:foreach($rv as $r):?><div class="review"><strong><?=e($r['name'])?> · <?=str_repeat('★',(int)$r['rating'])?></strong><p><?=e($r['comment'])?></p></div><?php endforeach;endif;?></div></div><aside class="panel booking-panel"><span class="eyebrow">Reserve a spot</span><h2><?=e(money((float)$loc['price_per_bag']))?> <small>/ bag / day</small></h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="create-booking"><input type="hidden" name="location_id" value="<?=(int)$loc['id']?>"><label>Drop-off<input name="dropoff_at" type="datetime-local" min="<?=date('Y-m-d\TH:i')?>" required></label><label>Pick-up<input name="pickup_at" type="datetime-local" min="<?=date('Y-m-d\TH:i')?>" required></label><label>Bags<select name="bags"><?php for($i=1;$i<=10;$i++):?><option value="<?=$i?>"><?=$i?> bag<?=$i>1?'s':''?></option><?php endfor;?></select></label><label>Notes <span class="muted">(optional)</span><textarea name="notes" rows="3" placeholder="Special instructions"></textarea></label><button class="btn btn-block" type="submit"><?=current_user()?'Confirm booking':'Sign in & book'?></button></form><p class="fine">Final total is calculated from bags and booking days. Capacity is checked before confirmation.</p></aside></section>
  <?php layout_end();exit;
}
